class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;
  bool Function(String path)? _isTrackInCurrentFolder;
  bool Function(String path)? _isTrackVisible;

  /// Bumped whenever browser scrolling/layout changes enough for
  /// [isTrackVisible] results to potentially change.
  final ValueNotifier<int> visibilityEpoch = ValueNotifier<int>(0);

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  bool isTrackInCurrentFolder(String path) =>
      _isTrackInCurrentFolder?.call(path) ?? false;

  /// True when [path] has a mounted row in the current visible region.
  bool isTrackVisible(String path) => _isTrackVisible?.call(path) ?? false;

  void bumpVisibilityEpoch() => visibilityEpoch.value++;
}

